('a1-med-01','A1','medien','a1-medien-1','phrase','Ich schreibe dir eine Nachricht.','Я напишу тебе сообщение.','Я напишу тобі повідомлення.',null,null,null,null,null,null,array['case_dativ']::text[],20000),
('a1-med-02','A1','medien','a1-medien-1','phrase','Schick mir bitte die Adresse.','Пришли мне, пожалуйста, адрес.','Надішли мені, будь ласка, адресу.',null,null,null,null,null,null,array[]::text[],20001),
('a1-med-03','A1','medien','a1-medien-1','phrase','Mein Akku ist leer.','У меня сел аккумулятор.','У мене сів акумулятор.',null,null,null,null,null,null,array[]::text[],20002),
('a1-med-04','A1','medien','a1-medien-1','phrase','Wie ist das WLAN-Passwort?','Какой пароль от Wi-Fi?','Який пароль від Wi-Fi?',null,null,null,null,null,null,array[]::text[],20003),
('a1-med-05','A1','medien','a1-medien-1','phrase','Ich rufe dich später an.','Я перезвоню тебе позже.','Я зателефоную тобі пізніше.','Ich rufe dich später ___.',null,null,null,null,null,array['separable_verb']::text[],20004),
('a1-med-06','A1','medien','a1-medien-1','phrase','Ich höre jeden Morgen Radio.','Я каждое утро слушаю радио.','Я щоранку слухаю радіо.',null,null,null,null,null,null,array[]::text[],20005),
('a1-med-07','A1','medien','a1-medien-1','phrase','Hast du die Nachrichten gesehen?','Ты видел(а) новости?','Ти бачив (бачила) новини?',null,null,null,null,null,null,array['perfekt']::text[],20006),
('a1-med-08','A1','medien','a1-medien-1','phrase','Die Verbindung ist schlecht.','Связь плохая.','Зв''язок поганий.',null,null,null,null,null,null,array[]::text[],20007),
('a1-med-09','A1','medien','a1-medien-1','word','das Handy','мобильный телефон','мобільний телефон',null,'Mein Handy ist kaputt.','Мой телефон сломался.','Мій телефон зламався.','das','die Handys',array[]::text[],20008),
('a1-med-10','A1','medien','a1-medien-1','word','die E-Mail','электронное письмо','електронний лист',null,'Ich lese meine E-Mails am Abend.','Я читаю почту вечером.','Я читаю пошту ввечері.','die','die E-Mails',array[]::text[],20009),
('a1-med-11','A1','medien','a1-medien-1','word','die Nachricht','сообщение; мн. ч. — новости','повідомлення; мн. — новини',null,'Ich habe deine Nachricht bekommen.','Я получил(а) твоё сообщение.','Я отримав (отримала) твоє повідомлення.','die','die Nachrichten',array[]::text[],20010),
('a1-med-12','A1','medien','a1-medien-1','word','der Fernseher','телевизор','телевізор',null,'Der Fernseher steht im Wohnzimmer.','Телевизор стоит в гостиной.','Телевізор стоїть у вітальні.','der','die Fernseher',array[]::text[],20011),
('a1-med-13','A1','medien','a1-medien-1','word','die Zeitung','газета','газета',null,'In der Zeitung steht ein Artikel über unsere Stadt.','В газете статья о нашем городе.','У газеті стаття про наше місто.','die','die Zeitungen',array[]::text[],20012),
('a1-med-14','A1','medien','a1-medien-1','word','der Computer','компьютер','комп''ютер',null,'Ich arbeite viel am Computer.','Я много работаю за компьютером.','Я багато працюю за комп''ютером.','der','die Computer',array[]::text[],20013)
